mapper.select:
SELECT * FROM session_student
WHERE session_id = #{sessionId}
  AND type = #{type}
  AND subject_id = #{subjectId}
LIMIT 1

SELECT * FROM session_student
WHERE session_id = #{sessionId}
ORDER BY booked_time ASC

SELECT * FROM session_student
WHERE type = #{type}
  AND subject_id = #{subjectId}
ORDER BY booked_time DESC

SELECT * FROM session_student
WHERE session_id = #{sessionId}
  AND type = #{type}
ORDER BY booked_time ASC

SELECT * FROM session_student
WHERE booked_time BETWEEN #{from} AND #{to}
ORDER BY booked_time ASC

SELECT COUNT(*) > 0 FROM session_student
WHERE session_id = #{sessionId}
  AND type = #{type}
  AND subject_id = #{subjectId}

SELECT COUNT(1) > 0
FROM session_student ss
INNER JOIN slot_sessions sls ON ss.session_id = sls.session_id
WHERE sls.assignment_id = #{assignmentId}
  AND (
    (ss.type = 'INDIVIDUAL' AND ss.subject_id = #{studentId})
    OR
    (ss.type IN ('GROUP', 'MIX') AND ss.subject_id IN (
      SELECT sg.group_id
      FROM sys_student_group sg
      WHERE sg.user_id = #{studentId}
    ))
  )

SELECT COUNT(1) > 0
FROM session_student ss
INNER JOIN slot_sessions sls ON ss.session_id = sls.session_id
WHERE sls.assignment_id = #{assignmentId}
  AND ss.type IN ('GROUP', 'MIX')
  AND ss.subject_id = #{groupId}
